import {ORIGINS} from './data.js?v=20261023-5';
const cache=new Map();let lastRequest=0;
export async function fetchRoads(courses,{signal}={}){const targets=courses.filter(c=>Number.isFinite(c.lat)&&Number.isFinite(c.lon)).slice(0,20);if(!targets.length)return new Map();const key=targets.map(c=>`${c.id}:${c.lon.toFixed(5)},${c.lat.toFixed(5)}`).join('|');if(cache.has(key))return structuredClone(cache.get(key));const wait=Math.max(0,2000-(Date.now()-lastRequest));if(wait)await new Promise((resolve,reject)=>{const timer=setTimeout(resolve,wait);signal?.addEventListener('abort',()=>{clearTimeout(timer);reject(new DOMException('Cancelled','AbortError'));},{once:true});});if(signal?.aborted)throw new DOMException('Cancelled','AbortError');lastRequest=Date.now();const origins=[ORIGINS.seoul,ORIGINS.busan],coordinates=[...origins,...targets].map(c=>`${c.lon},${c.lat}`).join(';'),destinations=targets.map((_,i)=>i+2).join(';');const endpoint=`https://routing.openstreetmap.de/routed-car/table/v1/driving/${coordinates}?sources=0;1&destinations=${destinations}&annotations=distance,duration`;const response=await fetch(endpoint,{signal});if(!response.ok)throw new Error(`경로 서버 ${response.status}`);const data=await response.json();if(data.code!=='Ok'||!Array.isArray(data.distances)||!Array.isArray(data.durations))throw new Error('도로 경로 미제공');const result=new Map();for(let i=0;i<targets.length;i++){const routes={};for(const [j,origin]of ['seoul','busan'].entries()){const meters=data.distances[j]?.[i],seconds=data.durations[j]?.[i];if(Number.isFinite(meters)&&Number.isFinite(seconds))routes[origin]={verified:true,mode:'driving',distanceKm:meters/1000,durationMin:seconds/60,estimated:true,traffic:false,provider:'OSRM / FOSSGIS',sourceUrl:'https://routing.openstreetmap.de/about.html',checkedAt:new Date().toISOString(),destination:{lat:targets[i].lat,lon:targets[i].lon,method:targets[i].positionAudit?'official-site-map-point':'source-representative-point'},snapDistanceMeters:data.destinations?.[i]?.distance??null,requiresSeaCrossing:targets[i].lat<34.1,warning:targets[i].lat<34.1?'제주-본토 차량 경로 · 해상연계/선박운항·대기 별도 확인':(data.destinations?.[i]?.distance??0)>1000?'대표점과 도로 스냅 1km 초과':null};}result.set(targets[i].id,routes);}cache.set(key,structuredClone(result));return result;}
